// Runs when the review is saved
export function stripScripts(text: string): string {
  return text.replace(/<script[\s\S]*?<\/script>/gi, "");
}

// Runs when the page shows it: stored text is parsed as HTML
export function renderReview(card: HTMLElement, review: Review): void {
  card.innerHTML = `<h3>${review.author}</h3><p>${review.text}</p>`;
}

// Saved as typed; protection happens here, at output
export function renderReview(card: HTMLElement, review: Review): void {
  const author = document.createElement("h3");
  author.textContent = review.author; // a text node, never parsed
  const text = document.createElement("p");
  text.textContent = review.text;
  const link = document.createElement("a");
  link.textContent = "Website";
  link.href = safeUrl(review.website); // URLs need a scheme check
  card.replaceChildren(author, text, link);
}

function safeUrl(raw: string): string {
  try {
    const url = new URL(raw);
    return ["https:", "http:"].includes(url.protocol) ? url.href : "#";
  } catch {
    return "#";
  }
}
